// ResutoDriver: drivers and delivery jobs.
// Owner: Agent D2 (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { isoDateTime, minor, optionalText, phoneE164, text, uuid, westernDigits } from './common';
import type { DeliveryStatus } from './state-machines';

export const deliveryContractsVersion = 1 as const;

export const VEHICLE_TYPES = ['motorbike', 'car', 'bicycle', 'scooter', 'on_foot', 'van'] as const;
export type VehicleType = (typeof VEHICLE_TYPES)[number];

export const DRIVER_AVAILABILITY = ['offline', 'available', 'busy', 'break'] as const;
export type DriverAvailability = (typeof DRIVER_AVAILABILITY)[number];

export const DRIVER_STATUSES = ['invited', 'active', 'suspended'] as const;
export type DriverStatus = (typeof DRIVER_STATUSES)[number];

/** Statuses in which a job is "live" on a driver (counts against availability). */
export const ACTIVE_DELIVERY_STATUSES = ['assigned', 'accepted', 'picked_up', 'en_route'] as const satisfies readonly DeliveryStatus[];

export const DELIVERY_FAILURE_REASONS = [
  'customer_unreachable', 'wrong_address', 'customer_refused', 'payment_refused', 'order_damaged', 'vehicle_issue', 'unsafe_location', 'order_cancelled', 'other',
] as const;
export type DeliveryFailureReason = (typeof DELIVERY_FAILURE_REASONS)[number];

const latitude = z.number().min(-90).max(90);
const longitude = z.number().min(-180).max(180);
const point = z.object({ latitude, longitude });
/** Optional coordinates attached to a driver action (recorded on delivery_events). */
const at = { latitude: latitude.optional().nullable(), longitude: longitude.optional().nullable() };

// ---------------------------------------------------------------------------
// Manager (delivery:dispatch)
// ---------------------------------------------------------------------------
export const driverUpdate = z.object({
  displayName: text(120).optional(),
  phone: phoneE164.optional().nullable(),
  vehicleType: z.enum(VEHICLE_TYPES).optional(),
  vehiclePlate: optionalText(30),
  branchIds: z.array(uuid).max(100).nullable().optional(),
  status: z.enum(['active', 'suspended']).optional(),
});
export type DriverUpdate = z.infer<typeof driverUpdate>;

export const deliveryJobQuery = z.object({
  status: z.string().max(200).optional(),           // comma separated DeliveryStatus values
  branchId: uuid.optional(),
  driverId: uuid.optional(),
  limit: z.coerce.number().int().min(1).max(200).default(50),
  cursor: z.string().max(200).optional(),
});

export const assignJob = z.object({
  driverId: uuid,
  /** assign: the driver gets the job directly (still accepts it); offer: the driver may accept or decline before it expires. */
  mode: z.enum(['assign', 'offer']).default('assign'),
  offerTtlSeconds: z.number().int().min(30).max(3600).default(120),
});
export type AssignJob = z.infer<typeof assignJob>;

export const cancelJob = z.object({ reason: text(300) });

export const settlementInput = z.object({
  driverId: uuid,
  jobIds: z.array(uuid).min(1).max(200),
  /** Cash physically handed over; must equal the collected cash on those jobs. */
  amountMinor: z.number().int().positive().max(1e13),
  note: optionalText(500),
});
export type SettlementInput = z.infer<typeof settlementInput>;

// ---------------------------------------------------------------------------
// Driver (delivery:drive)
// ---------------------------------------------------------------------------
export const availabilityInput = z.object({ availability: z.enum(DRIVER_AVAILABILITY) });

export const deviceRegistration = z.object({
  platform: z.enum(['web', 'ios', 'android']),
  deviceId: z.string().trim().min(8).max(200),
  pushToken: z.string().trim().max(4096).optional().nullable(),
  appVersion: z.string().trim().max(40).optional().nullable(),
});
export type DeviceRegistration = z.infer<typeof deviceRegistration>;

export const locationBatch = z.object({
  points: z.array(point.extend({
    accuracyM: z.number().min(0).max(100_000).optional().nullable(),
    recordedAt: isoDateTime.optional(),
  })).min(1).max(50),
});
export type LocationBatch = z.infer<typeof locationBatch>;

export const driverAction = z.object({ ...at, note: optionalText(300) });

export const declineJob = z.object({ ...at, reason: optionalText(300) });

export const deliverJob = z.object({
  ...at,
  recipientName: optionalText(120),
  proofMediaId: uuid.optional().nullable(),
  /** 4-digit code the customer received; optional, verified when given. */
  otp: westernDigits(z.string().regex(/^\d{4}$/, '4 digits')).optional().nullable(),
  /** Cash collected for COD jobs; must equal what is still due. */
  cashCollectedMinor: minor.optional(),
  note: optionalText(300),
}).refine((v) => !!(v.recipientName || v.proofMediaId || v.otp), { message: 'Add a photo, the recipient name or the delivery code', path: ['recipientName'] });
export type DeliverJob = z.infer<typeof deliverJob>;

export const failJob = z.object({ ...at, reason: z.enum(DELIVERY_FAILURE_REASONS), note: optionalText(300) });
export type FailJob = z.infer<typeof failJob>;

// ---------------------------------------------------------------------------
// Response shapes (camelCase, money in minor units)
// ---------------------------------------------------------------------------
export interface DeliveryDropoff {
  line1: string;
  area: string | null;
  city: string | null;
  notes: string | null;
  customerName: string | null;
  customerPhone: string | null;
  latitude: number | null;
  longitude: number | null;
}

export interface DeliveryJobView {
  id: string;
  orderId: string;
  orderNumber: string;
  orderStatus: string;
  branchId: string;
  branchName: string | null;
  status: DeliveryStatus;
  driverId: string | null;
  driverName: string | null;
  dropoff: DeliveryDropoff;
  pickup: { latitude: number | null; longitude: number | null; address: string | null };
  distanceM: number | null;
  etaAt: string | null;
  currency: string;
  orderTotalMinor: number;
  codAmountMinor: number;
  cashCollectedMinor: number;
  cashStatus: 'none' | 'pending' | 'collected' | 'settled';
  hasOtp: boolean;
  offer: { id: string; driverId: string; expiresAt: string } | null;
  failureReason: string | null;
  proofRecipient: string | null;
  assignedAt: string | null;
  acceptedAt: string | null;
  pickedUpAt: string | null;
  deliveredAt: string | null;
  createdAt: string;
  version: number;
  navigationUrl: string | null;
}

export interface DriverView {
  id: string;
  userId: string | null;
  displayName: string;
  phone: string | null;
  vehicleType: VehicleType;
  vehiclePlate: string | null;
  branchIds: string[] | null;
  status: DriverStatus;
  availability: DriverAvailability;
  lastLocation: { latitude: number; longitude: number; at: string } | null;
  activeJobs: number;
  cashOnHandMinor: number;
}

// ---------------------------------------------------------------------------
// FT-09 delivery zones and the public service area (opening hours + zones)
// ---------------------------------------------------------------------------
export const DELIVERY_ZONE_KINDS = ['radius', 'polygon', 'area'] as const;
export type DeliveryZoneKind = (typeof DELIVERY_ZONE_KINDS)[number];
const latLng = z.tuple([z.number().min(-90).max(90), z.number().min(-180).max(180)]);
export const deliveryZoneInput = z.object({
  branchId: uuid,
  name: z.string().trim().min(1).max(80),
  nameAr: z.string().trim().min(1).max(80).nullable().optional(),
  kind: z.enum(DELIVERY_ZONE_KINDS),
  radiusM: z.number().int().min(100).max(100_000).nullable().optional(),
  /** [latitude, longitude] ring, 3–200 points. */
  polygon: z.array(latLng).min(3).max(200).nullable().optional(),
  feeMinor: minor.default(0),
  minOrderMinor: minor.default(0),
  etaMin: z.number().int().min(5).max(600).nullable().optional(),
  sortOrder: z.number().int().min(0).max(999).default(0),
  isActive: z.boolean().default(true),
}).strict().superRefine((v, c) => {
  if (v.kind === 'radius' && !v.radiusM) c.addIssue({ code: 'custom', path: ['radiusM'], message: 'A radius zone needs a radius in metres' });
  if (v.kind === 'polygon' && !v.polygon) c.addIssue({ code: 'custom', path: ['polygon'], message: 'A polygon zone needs at least 3 points' });
  if (v.kind !== 'radius' && v.radiusM) c.addIssue({ code: 'custom', path: ['radiusM'], message: 'Only radius zones have a radius' });
  if (v.kind !== 'polygon' && v.polygon) c.addIssue({ code: 'custom', path: ['polygon'], message: 'Only polygon zones have points' });
});
export type DeliveryZoneInput = z.infer<typeof deliveryZoneInput>;
export interface DeliveryZone {
  id: string; branchId: string; name: string; nameAr: string | null; kind: DeliveryZoneKind; radiusM: number | null;
  polygon: Array<[number, number]> | null; feeMinor: number; minOrderMinor: number; etaMin: number | null; sortOrder: number; isActive: boolean;
}
/** Public, per branch: is it open now (branch time zone), when it opens next, and the zones a guest can choose. */
export interface PublicServiceArea {
  branchId: string;
  timezone: string;
  openNow: boolean;
  /** Next opening when closed now; null when always open or no hours are set. */
  nextOpenAt: string | null;
  hoursSet: boolean;
  delivery: {
    offered: boolean;
    /** Zones the guest chooses from (geometry is not exposed; radius/polygon zones also need a shared location). */
    zones: Array<{ id: string; name: string; nameAr: string | null; kind: DeliveryZoneKind; feeMinor: number; minOrderMinor: number; etaMin: number | null }>;
    defaultFeeMinor: number;
    defaultMinOrderMinor: number;
  };
}

/**
 * FT-14: what a guest's tracking page may show about the delivery. The driver's position is shared only while the
 * job is en route (never before pickup), rounded to about 100 m and only when fresh; the driver is named by first
 * name only; the drop-off point is rounded too (the tracking link can be forwarded).
 */
export interface PublicDeliveryTracking {
  status: DeliveryStatus;
  etaAt: string | null;
  driverFirstName: string | null;
  pickedUpAt: string | null;
  deliveredAt: string | null;
  restaurant: { latitude: number; longitude: number } | null;
  destination: { latitude: number; longitude: number } | null;
  driver: { latitude: number; longitude: number; at: string } | null;
}
